body.script:
(async function() {
  const ns = "http://www.w3.org/1999/xhtml";

  // Auto-detect BASE: if on a CDN, fall back to the Caddy domain via referrer or prompt.
  // We derive BASE from wherever THIS svg is being served from — if it's a CDN host,
  // we use the stored BASE or ask the user to set one via localStorage("xyloraBase").
  const CDN_HOSTS = ["cdn.statically.io", "cdn.jsdelivr.net", "raw.githubusercontent.com", "gitlab.com", "github.com"];
  const isCDN = CDN_HOSTS.some(h => location.hostname.includes(h));

  // Allow runtime override via localStorage so users can set their own domain
  // e.g. localStorage.setItem("xyloraBase", "https://mysite.com")
  let BASE = localStorage.getItem("xyloraBase") || "";

  if (!BASE && isCDN) {
    // No base set and on CDN — show a one-time prompt to configure
    BASE = prompt("Enter your Xylora server URL (e.g. https://yourdomain.com):", "https://") || "";
    if (BASE) {
      BASE = BASE.replace(/\/$/, "");
      localStorage.setItem("xyloraBase", BASE);
    }
  }

  if (!BASE) {
    // Not on CDN, use current origin
    BASE = location.origin;
  }

  BASE = BASE.replace(/\/$/, "");

  const body = document.querySelector("body");
  const svgRoot = document.documentElement;

  const head = document.createElementNS(ns, "head");
  body.prepend(head);

  const htmlRoot = body.parentElement?.namespaceURI === ns ? body.parentElement : body;
  try { Object.defineProperty(document, "head",            { configurable:true, get() { return head; } }); } catch(e) {}
  try { Object.defineProperty(document, "body",            { configurable:true, get() { return body; } }); } catch(e) {}
  try { Object.defineProperty(document, "documentElement", { configurable:true, get() { return htmlRoot; } }); } catch(e) {}
  try {
    Object.defineProperty(svgRoot, "className", {
      configurable: true,
      get() { return svgRoot.getAttribute("class") || ""; },
      set(v)  { svgRoot.setAttribute("class", v || ""); },
    });
  } catch(e) {}

  const _ce = document.createElement.bind(document);
  document.createElement = (tag, opts) =>
    typeof tag === "string" ? document.createElementNS(ns, tag, opts) : _ce(tag, opts);

  // --- Favicon / tab cloak ---
  function applyFavicon() {
    const PRESETS = {
      google:          { icon: BASE + "/images/icons/google.ico",          title: "Google" },
      bing:            { icon: BASE + "/images/icons/bing.ico",            title: "Bing" },
      gmail:           { icon: BASE + "/images/icons/gmail.ico",           title: "Gmail" },
      desmos:          { icon: BASE + "/images/icons/desmos.ico",          title: "Desmos | Graphing Calculator" },
      googleclassroom: { icon: BASE + "/images/icons/googleclassroom.ico", title: "Home - Classroom" },
      wikipedia:       { icon: BASE + "/images/icons/wikipedia.ico",       title: "Wikipedia" },
      chrometab:       { icon: BASE + "/images/icons/chromenewtab.ico",    title: "New Tab" },
      googledrive:     { icon: BASE + "/images/icons/googledrive.ico",     title: "My Drive - Google Drive" },
      clever:          { icon: BASE + "/images/icons/clever.ico",          title: "Clever | Portal" },
    };
    const key = localStorage.getItem("tabCloakPreset");
    const p   = key && PRESETS[key];
    head.querySelectorAll("link[rel~='icon'],link[rel='shortcut icon']").forEach(n => {
      if (!n.getAttribute("data-tabcloak")) n.remove();
    });
    ["icon", "shortcut icon"].forEach(rel => {
      const l = document.createElementNS(ns, "link");
      l.rel  = rel;
      l.href = p ? p.icon : BASE + "/images/icons/favicon.ico";
      l.type = "image/x-icon";
      if (p) l.setAttribute("data-tabcloak", "1");
      head.appendChild(l);
    });
    if (p?.title) document.title = p.title;
  }

  applyFavicon();
  window.addEventListener("storage", applyFavicon);

  // --- Script/link loader ---
  async function appendHeadNode(def) {
    const el = document.createElementNS(ns, def.tag);
    for (const [k, v] of Object.entries(def.attrs || {})) el.setAttribute(k, v);
    if (def.text) el.textContent = def.text;
    head.appendChild(el);
    if (def.tag === "script" && def.attrs?.src) {
      await new Promise(r => {
        const t = setTimeout(r, 12000);
        el.onload  = () => { clearTimeout(t); r(); };
        el.onerror = () => { clearTimeout(t); r(); };
      });
    }
  }

  const headNodes = [
    { tag: "meta", attrs: { charset: "UTF-8" } },
    { tag: "meta", attrs: { name: "viewport", content: "width=device-width, initial-scale=1.0" } },
    { tag: "link", attrs: { rel: "stylesheet", href: "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" } },
    { tag: "script", attrs: { src: BASE + "/storage/js/c.js" } },
    { tag: "script", attrs: { src: BASE + "/socket.io/socket.io.js" } },
  ];

  for (const def of headNodes) {
    await appendHeadNode(def);
  }

  applyFavicon();

  // --- Wire up iframe and taskbar ---
  const iframe  = document.getElementById("frame");
  const taskbar = document.getElementById("taskbar");
  const closeBtn = document.getElementById("closeTaskbar");
  const toast   = document.getElementById("toast");
  const buttons = document.querySelectorAll(".taskbar-btn[data-page]");

  // Set iframe src now that BASE is known
  iframe.src = BASE + "/home.html";

  // Stamp full URLs onto buttons so data-src works with c.js openAbout/openBlob
  buttons.forEach(btn => {
    btn.dataset.src = BASE + btn.dataset.page;
  });

  function setActiveBySrc(src) {
    buttons.forEach(btn => btn.classList.toggle("active", btn.dataset.src === src));
  }

  function navigate(btn) {
    iframe.src = btn.dataset.src;
    setActiveBySrc(btn.dataset.src);
  }

  buttons.forEach(btn => btn.addEventListener("click", () => navigate(btn)));
  setActiveBySrc(BASE + "/home.html");

  function syncActive() {
    try {
      const path = iframe.contentWindow.location.pathname;
      if (path) setActiveBySrc(BASE + path);
    } catch(e) {
      setActiveBySrc(iframe.src);
    }
  }

  iframe.addEventListener("load", syncActive);
  setInterval(syncActive, 500);

  let taskbarVisible = true;
  let taskbarState   = "open";
  let toastTimeout;

  function showToast(txt, time = 1500) {
    if (!toast) return;
    toast.textContent = txt;
    toast.classList.add("show");
    clearTimeout(toastTimeout);
    toastTimeout = setTimeout(() => toast.classList.remove("show"), time);
  }

  function showTaskbar() { taskbarVisible = true; taskbarState = "open"; taskbar.classList.remove("hidden"); taskbar.style.pointerEvents = "auto"; }
  function hideTaskbar() { taskbarVisible = false; taskbarState = "hidden"; taskbar.classList.add("hidden"); taskbar.style.pointerEvents = "none"; }

  closeBtn.addEventListener("click", () => {
    if (taskbarState !== "open") return;
    taskbarState = "closing";
    hideTaskbar();
    showToast("press \\ to reopen taskbar (above enter key)");
    setTimeout(() => { taskbarState = "hidden"; }, 250);
  });

  function handleBackslash(e) {
    if (e.code !== "Backslash" || e.repeat) return;
    e.preventDefault();
    taskbarVisible ? hideTaskbar() : showTaskbar();
  }

  window.addEventListener("keydown", handleBackslash, true);
  iframe.addEventListener("load", () => {
    try { iframe.contentWindow.addEventListener("keydown", handleBackslash, true); } catch(e) {}
    applyFavicon();
  });

  document.getElementById("cloakBtn").addEventListener("click", () => {
    localStorage.getItem("blobButton") === "true" ? openBlob() : openAbout();
  });

  // --- Socket.io ---
  try {
    const socket = io(BASE);
    let deviceId = localStorage.getItem("deviceId");
    if (!deviceId) {
      deviceId = crypto.randomUUID();
      localStorage.setItem("deviceId", deviceId);
    }
    socket.emit("register-device", deviceId);
    socket.on("online-users", (count) => {
      if (!iframe || !iframe.contentWindow) return;
      iframe.contentWindow.postMessage({ type: "online-users", count }, "*");
    });
  } catch(e) { console.warn("Socket.io unavailable:", e); }

  setTimeout(() => {
    document.dispatchEvent(new Event("DOMContentLoaded", { bubbles: true }));
    window.dispatchEvent(new Event("load"));
    applyFavicon();
  }, 50);

})();
